create extension if not exists pgcrypto;
create extension if not exists btree_gist;
create type public.shop_role as enum ('owner','manager','piercer');
create type public.booking_status as enum ('requested','confirmed','completed','rejected','cancelled','no_show');
create type public.payment_method as enum ('cash','gcash','maya','bank_transfer','card','other');
create type public.sale_status as enum ('draft','completed','voided');

create table public.shops(id uuid primary key default gen_random_uuid(),slug text unique not null check(slug~'^[a-z0-9]+(?:-[a-z0-9]+)*$'),name text not null,email text not null,phone text,address text,timezone text not null default 'Asia/Manila' check(timezone='Asia/Manila'),currency text not null default 'PHP' check(currency='PHP'),active boolean not null default true,created_at timestamptz not null default now());
create table public.shop_settings(shop_id uuid primary key references public.shops on delete cascade,cancellation_cutoff_hours int not null default 24,minimum_age int not null default 18,guardian_required_under int,reminder_hours int[] not null default '{24}',cancellation_policy text,business_hours jsonb not null default '{}');
create table public.memberships(id uuid primary key default gen_random_uuid(),shop_id uuid not null references public.shops on delete cascade,user_id uuid not null references auth.users on delete cascade,role public.shop_role not null,display_name text not null,active boolean not null default true,unique(shop_id,user_id));
create table public.services(id uuid primary key default gen_random_uuid(),shop_id uuid not null references public.shops on delete cascade,name text not null,body_area text not null,duration_minutes int not null check(duration_minutes>0),price_cents int not null check(price_cents>=0),active boolean not null default true);
create table public.service_piercers(shop_id uuid not null references public.shops on delete cascade,service_id uuid not null references public.services on delete cascade,membership_id uuid not null references public.memberships on delete cascade,primary key(service_id,membership_id));
create table public.products(id uuid primary key default gen_random_uuid(),shop_id uuid not null references public.shops on delete cascade,name text not null,price_cents int not null check(price_cents>=0),active boolean not null default true);
create table public.staff_availability(id uuid primary key default gen_random_uuid(),shop_id uuid not null references public.shops on delete cascade,membership_id uuid not null references public.memberships on delete cascade,weekday smallint check(weekday between 0 and 6),starts_at time not null,ends_at time not null check(ends_at>starts_at));
create table public.closures(id uuid primary key default gen_random_uuid(),shop_id uuid not null references public.shops on delete cascade,starts_at timestamptz not null,ends_at timestamptz not null check(ends_at>starts_at),reason text);
create table public.customers(id uuid primary key default gen_random_uuid(),shop_id uuid not null references public.shops on delete cascade,first_name text not null,last_name text not null,email text not null,phone text not null,created_at timestamptz not null default now());
create table public.bookings(id uuid primary key default gen_random_uuid(),shop_id uuid not null references public.shops on delete cascade,customer_id uuid not null references public.customers,service_id uuid not null references public.services,assigned_piercer_id uuid references public.memberships,status public.booking_status not null default 'requested',body_area text,preferred_piercer_id uuid references public.memberships,preferred_start timestamptz,preferred_end timestamptz,starts_at timestamptz,ends_at timestamptz,notes text,customer_token_hash text unique,token_revoked_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check((status<>'confirmed')or(assigned_piercer_id is not null and starts_at is not null and ends_at>starts_at)));
alter table public.bookings add constraint no_piercer_overlap exclude using gist(assigned_piercer_id with =,tstzrange(starts_at,ends_at,'[)') with &&) where(status='confirmed');
create table public.booking_changes(id uuid primary key default gen_random_uuid(),shop_id uuid not null references public.shops on delete cascade,booking_id uuid not null references public.bookings on delete cascade,kind text not null,requested_start timestamptz,requested_end timestamptz,status text not null default 'pending',note text,created_at timestamptz not null default now());
create table public.form_definitions(id uuid primary key default gen_random_uuid(),shop_id uuid not null references public.shops on delete cascade,kind text not null check(kind in('booking','consent')),version int not null,title text not null,fields jsonb not null,published_at timestamptz,unique(shop_id,kind,version));
create table public.consent_submissions(id uuid primary key default gen_random_uuid(),shop_id uuid not null references public.shops on delete cascade,booking_id uuid not null unique references public.bookings,form_definition_id uuid not null references public.form_definitions,answers jsonb not null,typed_acknowledgement text not null,guardian jsonb,accepted_at timestamptz not null);
create table public.sales(id uuid primary key default gen_random_uuid(),shop_id uuid not null references public.shops on delete cascade,booking_id uuid references public.bookings,customer_id uuid references public.customers,status public.sale_status not null default 'draft',subtotal_cents int not null default 0,discount_cents int not null default 0,total_cents int not null default 0,completed_at timestamptz,completed_by uuid references auth.users,created_at timestamptz not null default now());
create table public.sale_items(id uuid primary key default gen_random_uuid(),shop_id uuid not null references public.shops on delete cascade,sale_id uuid not null references public.sales on delete cascade,item_type text not null check(item_type in('service','product')),source_id uuid,description text not null,quantity int not null check(quantity>0),unit_price_cents int not null,discount_cents int not null default 0);
create table public.payments(id uuid primary key default gen_random_uuid(),shop_id uuid not null references public.shops on delete cascade,sale_id uuid not null references public.sales,method public.payment_method not null,amount_cents int not null check(amount_cents>0),reference text,received_at timestamptz not null default now(),received_by uuid references auth.users);
create table public.sale_adjustments(id uuid primary key default gen_random_uuid(),shop_id uuid not null references public.shops on delete cascade,sale_id uuid not null references public.sales,kind text not null check(kind in('void','refund')),amount_cents int not null,reason text not null,actor_id uuid not null references auth.users,created_at timestamptz not null default now());
create table public.notifications(id uuid primary key default gen_random_uuid(),shop_id uuid not null references public.shops on delete cascade,booking_id uuid references public.bookings,kind text not null,recipient text not null,idempotency_key text unique not null,status text not null default 'pending',attempts int not null default 0,sent_at timestamptz,last_error text);
create table public.audit_events(id bigint generated always as identity primary key,shop_id uuid not null references public.shops on delete cascade,actor_id uuid references auth.users,event_type text not null,entity_type text not null,entity_id uuid,metadata jsonb not null default '{}',created_at timestamptz not null default now());

create or replace function public.is_shop_member(target uuid,allowed public.shop_role[] default array['owner','manager','piercer']::public.shop_role[])returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.memberships m where m.shop_id=target and m.user_id=auth.uid() and m.active and m.role=any(allowed));$$;
create or replace function public.can_access_booking(target uuid,piercer uuid)returns boolean language sql stable security definer set search_path='' as $$select public.is_shop_member(target,array['owner','manager']::public.shop_role[])or exists(select 1 from public.memberships m where m.id=piercer and m.user_id=auth.uid() and m.role='piercer');$$;

do $$declare t text;begin foreach t in array array['shops','shop_settings','memberships','services','service_piercers','products','staff_availability','closures','customers','bookings','booking_changes','form_definitions','consent_submissions','sales','sale_items','payments','sale_adjustments','notifications','audit_events'] loop execute format('alter table public.%I enable row level security',t);end loop;end$$;
create policy shop_read on public.shops for select using(public.is_shop_member(id));
create policy member_read on public.memberships for select using(public.is_shop_member(shop_id));
create policy booking_read on public.bookings for select using(public.can_access_booking(shop_id,assigned_piercer_id));
create policy booking_manage on public.bookings for all using(public.is_shop_member(shop_id,array['owner','manager']::public.shop_role[]))with check(public.is_shop_member(shop_id,array['owner','manager']::public.shop_role[]));
create policy consent_read on public.consent_submissions for select using(exists(select 1 from public.bookings b where b.id=booking_id and public.can_access_booking(b.shop_id,b.assigned_piercer_id)));
create policy customer_read on public.customers for select using(public.is_shop_member(shop_id,array['owner','manager']::public.shop_role[])or exists(select 1 from public.bookings b where b.customer_id=customers.id and public.can_access_booking(b.shop_id,b.assigned_piercer_id)));
create policy sales_read on public.sales for select using(public.is_shop_member(shop_id,array['owner','manager']::public.shop_role[])or exists(select 1 from public.bookings b where b.id=booking_id and public.can_access_booking(b.shop_id,b.assigned_piercer_id)));
create policy management_audit_read on public.audit_events for select using(public.is_shop_member(shop_id,array['owner','manager']::public.shop_role[]));
create policy settings_read on public.shop_settings for select using(public.is_shop_member(shop_id));
create policy settings_owner_write on public.shop_settings for all using(public.is_shop_member(shop_id,array['owner']::public.shop_role[]))with check(public.is_shop_member(shop_id,array['owner']::public.shop_role[]));
create policy services_read on public.services for select using(public.is_shop_member(shop_id));
create policy services_manage on public.services for all using(public.is_shop_member(shop_id,array['owner','manager']::public.shop_role[]))with check(public.is_shop_member(shop_id,array['owner','manager']::public.shop_role[]));
create policy products_read on public.products for select using(public.is_shop_member(shop_id));
create policy products_manage on public.products for all using(public.is_shop_member(shop_id,array['owner','manager']::public.shop_role[]))with check(public.is_shop_member(shop_id,array['owner','manager']::public.shop_role[]));
create policy piercer_availability_read on public.staff_availability for select using(public.is_shop_member(shop_id));
create policy closures_read on public.closures for select using(public.is_shop_member(shop_id));
create policy forms_management_read on public.form_definitions for select using(public.is_shop_member(shop_id,array['owner','manager']::public.shop_role[]));
create policy sale_items_read on public.sale_items for select using(public.is_shop_member(shop_id));
create policy payments_management_read on public.payments for select using(public.is_shop_member(shop_id,array['owner','manager']::public.shop_role[]));
create policy adjustments_management_read on public.sale_adjustments for select using(public.is_shop_member(shop_id,array['owner','manager']::public.shop_role[]));
create policy notifications_management_read on public.notifications for select using(public.is_shop_member(shop_id,array['owner','manager']::public.shop_role[]));

create or replace function public.protect_completed_sale()returns trigger language plpgsql set search_path='' as $$begin if old.status='completed'then raise exception 'Completed sales are immutable; create an adjustment';end if;return new;end$$;
create trigger completed_sales_immutable before update or delete on public.sales for each row execute function public.protect_completed_sale();
insert into storage.buckets(id,name,public)values('booking-photos','booking-photos',false)on conflict(id)do nothing;
